@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
struct Params {amount:f32, trailTime:f32, // @default 0.032 Short exposure, in seconds; grains remain visible.
};
@fragment fn fs(@location(0) uv:vec2f)->@location(0) vec4f {
 let a=textureSampleLevel(inputTexture,inputSampler,uv,0.).rgb;
 let d=vec2i(textureDimensions(inputTexture1));let b=textureLoad(inputTexture1,clamp(vec2i(uv*vec2f(d)),vec2i(0),d-1),0).rgb;
 let decay=exp(-frameU.deltaTime/max(params.trailTime,.001));return vec4f(max(a,b*decay),1.);
}

struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;
@group(0) @binding(6) var inputTexture3: texture_2d<f32>;
struct Params {amount:f32, glow:f32, // @default 0.22 Light around the separate droplets.
};
@fragment fn fs(@location(0) uv:vec2f)->@location(0) vec4f {
 let c=textureSampleLevel(inputTexture,inputSampler,uv,0.).rgb;
 let d=vec2i(textureDimensions(inputTexture1));let halo=textureLoad(inputTexture1,clamp(vec2i(uv*vec2f(d)),vec2i(0),d-1),0).rgb;
 let md=vec2i(textureDimensions(inputTexture2));let mask=textureLoad(inputTexture2,clamp(vec2i(uv*vec2f(md)),vec2i(0),md-1),0).r;
 let bd=vec2i(textureDimensions(inputTexture3));let rear=textureLoad(inputTexture3,clamp(vec2i(uv*vec2f(bd)),vec2i(0),bd-1),0).rgb;
 let radiance=c+rear+halo*params.glow;
 return vec4f((vec3f(1.)-exp(-radiance*3.0))*(1.-mask),1.);
}

