struct Params {
 depth:f32, // @default 0.10 The second curtain stays dim enough to preserve open gaps.

 speed:f32, // @default 0.38 Feed velocity at the uneven lip.
 gravity:f32, // @default 2.2 Downward acceleration for ballistic drops.
 drag:f32, // @default 0.5 Air resistance, scaled by droplet size.
 splash:f32, // @default 1.2 Fraction of incoming momentum redistributed into spray.
 swirl:f32, // @default 1.2 Shared air turbulence; sampled from the middle atlas panel.
 brightness:f32, // @default 0.85 Optical energy in the water.
 velocityShade:f32, // @default 0.6 Speed-dependent highlight contrast.
 grainSize:f32, // @default 1.1 Drop size multiplier.
 aspect:f32, // @default 1.7777778 Width over height in world units.
 motionRate:f32, // @default 0.45 Simulation time scale.
 folds:f32, // @default 0.9 Growth of breakup with falling distance.
 strandLength:f32, // @default 0.038 Exposure of a coarse drop, in simulation seconds.
 colorSpeed:f32, // @default 2.4 Speed at the top end of the colour ramp.
 colorCurve:f32, // @default 0.8 Curve applied before the velocity LUT lookup.
}
fn hash01(v:u32)->f32 {let s=v*747796405u+2891336453u;let w=((s>>((s>>28u)+4u))^s)*277803737u;return f32((w>>22u)^w)*(1./4294967296.);}
fn noise2(p:vec2f)->f32 {
 let i=vec2i(floor(p));let f=fract(p);let u=f*f*(3.-2.*f);
 let a=hash01((bitcast<u32>(i.x)*1597334677u)^(bitcast<u32>(i.y)*3812015801u));
 let b=hash01((bitcast<u32>(i.x+1)*1597334677u)^(bitcast<u32>(i.y)*3812015801u));
 let c=hash01((bitcast<u32>(i.x)*1597334677u)^(bitcast<u32>(i.y+1)*3812015801u));
 let d=hash01((bitcast<u32>(i.x+1)*1597334677u)^(bitcast<u32>(i.y+1)*3812015801u));
 return mix(mix(a,b,u.x),mix(c,d,u.x),u.y)*2.-1.;
}
fn turbulence(p:vec2f)->f32 {
 return .57*noise2(p)+.28*noise2(p*2.07+vec2f(17.1,9.3))+.15*noise2(p*4.13-vec2f(8.2,3.7));
}
// Atlas contract: three 640x360 panels, saved as a fixed 1920x360 texture.
fn atlas(uv:vec2f,panel:f32)->vec4f {
 let xy=clamp(uv,vec2f(0.),vec2f(1.));let texel=panel*640.+xy.x*639.;
 return fieldAt(vec3f(2.*texel/1919.-1.,1.-2.*xy.y,0.));
}
fn sampleWorld(p:vec2f,aspect:f32,panel:f32)->vec4f {return atlas(vec2f(p.x/(2.*aspect)+.5,.5-p.y*.5),panel);}
fn emitter(channel:u32,t:f32,aspect:f32)->vec2f {
 let h=hash01(channel^91733u)*43.;let bank=u32(floor(h));let within=fract(h);
 let span=2.*aspect/43.;let at=-aspect+(f32(bank)+.12+.76*hash01(bank^842u))*span;
 let centre=at+.10*noise2(vec2f(at*3.3,t*.1+9.));
 let pressure=.5+.5*noise2(vec2f(f32(bank)*.21,t*.24));
 let width=span*(.35+.75*pressure);
 let x=centre+(within-.5)*width+.012*noise2(vec2f(f32(bank),t*.2));
 return vec2f(x,1.045+.018*noise2(vec2f(f32(bank)*2.3,7.)));
}
fn birthVelocity(channel:u32,t:f32,feed:f32)->vec2f {
 let bank=floor(hash01(channel^91733u)*18.);
 let angle=.22*noise2(vec2f(bank*1.7,t*.35))+.08*noise2(vec2f(f32(channel)*.07,3.));
 return vec2f(feed*angle,-feed*(.8+.4*hash01(channel^991u)));
}
fn velocityColor(v:vec2f,hit:f32,maxSpeed:f32,curve:f32)->vec3f {
 let u=pow(clamp(length(v)/maxSpeed+hit*.18,0.,1.),curve);
 return atlas(vec2f(u,.5),2.).rgb;
}
fn process(p:Point,ctx:PointCtx)->Point {
 var q=p;let id=ctx.index;var channel=select(u32(q.motion.w),id/64u,q.motion.z<.5);
 let grain=hash01(id^71891u);let kind=select(.40,1.,hash01(id^81911u)>.43);
 let impactKind=select(.40,1.,hash01(id^6171u)>.32);
 let dt=ctx.delta*ctx.params.motionRate;let t=ctx.absTime*ctx.params.motionRate+13.7;
 var pos=q.position.xy;var vel=q.motion.xy;var hit=max(q.motion.z-1.,0.)*exp(-dt*1.5);
 var lip=emitter(channel,t,ctx.params.aspect);
 if(q.motion.z<.5){
  pos.y=hash01(id^8177u)*2.2-1.1;let d=max(lip.y-pos.y,0.);
  let age=(sqrt(ctx.params.speed*ctx.params.speed+2.*ctx.params.gravity*d)-ctx.params.speed)/ctx.params.gravity;
  lip=emitter(channel,t-age,ctx.params.aspect);vel=birthVelocity(channel,t-age,ctx.params.speed);
  pos.x=lip.x+vel.x*age;vel.y=-sqrt(vel.y*vel.y+2.*ctx.params.gravity*d);

 }
 let fallen=max(1.045-pos.y,0.);
 let fractureAt=.12+1.4*hash01(id^393u);
 let broken=smoothstep(fractureAt,fractureAt+.30,fallen)*ctx.params.folds;
 var drop=max(broken*kind,smoothstep(.015,.22,hit)*impactKind);
 let radius=mix(.95+.35*grain,.12+.14*grain,drop);
 let air=sampleWorld(pos,ctx.params.aspect,1.);
 let relative=vel-air.xy;
 let resistance=ctx.params.drag*.35/(radius*radius);
 vel=air.xy+relative*exp(-resistance*length(relative)*dt);vel.y-=ctx.params.gravity*dt;
 let steps=u32(clamp(ceil(length(vel)*dt/.004),1.,24.));let ds=dt/f32(steps);
 for(var j=0u;j<steps;j++){
  pos+=vel*ds;

 }
 if(pos.y< -1.18||abs(pos.x)>ctx.params.aspect+.70){
  channel=u32(pointRand(id,71u)*f32(ctx.count/64u));pos=emitter(channel,t,ctx.params.aspect);
  pos.y+=grain*.055;vel=birthVelocity(channel,t,ctx.params.speed);hit=0.;drop=0.;
 }
 drop=max(drop,smoothstep(.015,.22,hit)*impactKind);
 q.position=vec3f(pos,0.);q.motion=vec4f(vel,1.+hit,f32(channel));q.droplet=drop;
 let speed=length(vel);let color=velocityColor(vel,hit,ctx.params.colorSpeed,ctx.params.colorCurve);
 let pulse=.45+.55*smoothstep(-.65,.65,noise2(vec2f(f32(channel%31u)*.39,t*.6-fallen*.45)));
 let moving=max(smoothstep(.03,.7,speed),hit*.7);
 let optical=select(select(.085,.065+.55*pow(grain,5.),drop>.12),.15,drop>=.62)*ctx.params.brightness*ctx.params.depth*(.55+.45*grain)*pulse*moving;
 let glint=1.+hit*(.4+2.*ctx.params.velocityShade)+air.z*drop*.25;
 q.tint=vec4f(mix(color,vec3f(1.,.94,.82),hit*.18)*optical*glint,.65);
 q.diameter=ctx.params.grainSize*mix(.65+.65*grain,.8+1.25*grain,drop);
 let exposure=ctx.params.strandLength*(.4+.9*grain)*mix(1.,.24,smoothstep(.06,.40,drop));
 var end=pos-vel*exposure;end.y-=.5*ctx.params.gravity*exposure*exposure;
 if(sampleWorld(end,ctx.params.aspect,0.).r<.002){
  var lo=0.;var hi=1.;
  for(var b=0;b<5;b++){let m=(lo+hi)*.5;let at=mix(pos,end,m);if(sampleWorld(at,ctx.params.aspect,0.).r>=.002){lo=m;}else{hi=m;}}
  end=mix(pos,end,lo);
 }
 q.tip=vec3f(end,0.);return q;
}

