struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
struct Params { enabled:f32, // @default 0 Demonstration collider; replace null_mask_input with your own mask.
 amount: f32, motion: f32, // @default 1 Animate the demonstration silhouette; replace null_mask_input with your own matte.
};
fn cap(p:vec2f,a:vec2f,b:vec2f,r:f32)->f32 {let ba=b-a;let t=clamp(dot(p-a,ba)/dot(ba,ba),0.,1.);return length(p-a-ba*t)-r;}
@fragment fn fs(@location(0) uv:vec2f)->@location(0) vec4f {
 let aspect=frameU.resolution.x/frameU.resolution.y;
 var p=vec2f((uv.x-.5)*2.*aspect,1.-2.*uv.y);
 let t=frameU.absTime*params.motion;
 p.x-=.06*sin(t*.42);
 let hand=vec2f(.92,.17+.15*sin(t*.55));
 var d=length((p-vec2f(-.10,.43))/vec2f(.12,.155))-1.;d*=.12;
 d=min(d,cap(p,vec2f(-.11,.23),vec2f(-.10,-.27),.16));
 d=min(d,cap(p,vec2f(-.20,.20),vec2f(-.35,-.05),.066));
 d=min(d,cap(p,vec2f(-.35,-.05),vec2f(-.44,-.34),.052));
 d=min(d,cap(p,vec2f(.0,.22),vec2f(.46,.17),.065));
 d=min(d,cap(p,vec2f(.46,.17),hand,.048));
 d=min(d,length(p-hand)-.060);
 d=min(d,cap(p,vec2f(-.18,-.28),vec2f(-.24,-.95),.075));
 d=min(d,cap(p,vec2f(-.025,-.28),vec2f(.10,-.95),.075));
 let m=1.-smoothstep(-.003,.003,d);return vec4f(vec3f(m*params.enabled),1.);
}

struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
struct Params { amount:f32, threshold:f32, // @default 0.5 Foreground threshold; white means solid.
 alphaChannel:f32, // @default 0 0 reads luminance; 1 reads alpha from a background-removed video.
 mirror:f32, // @default 0 Set to 1 to mirror the mask horizontally.
};
@fragment fn fs(@location(0) uv:vec2f)->@location(0) vec4f {
 let dim=vec2f(textureDimensions(inputTexture));
 let u=vec2f(mix(uv.x,1.-uv.x,params.mirror),uv.y);
 let c=textureLoad(inputTexture,clamp(vec2i(u*dim),vec2i(0),vec2i(dim)-1),0);
 let v=mix(dot(c.rgb,vec3f(.2126,.7152,.0722)),c.a,params.alphaChannel);
 let m=select(0.,1.,v>=params.threshold);return vec4f(vec3f(m),1.);
}

struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
struct Params {amount:f32,};
fn mask(p:vec2i)->f32 {let d=vec2i(textureDimensions(inputTexture));if(any(p<vec2i(0))||any(p>=d)){return 0.;}return textureLoad(inputTexture,p,0).r;}
@fragment fn fs(@location(0) uv:vec2f)->@location(0) vec4f {
 let d=vec2i(textureDimensions(inputTexture));let p=clamp(vec2i(uv*vec2f(d)),vec2i(0),d-1);let m=mask(p);
 let edge=abs(m-mask(p+vec2i(1,0)))+abs(m-mask(p-vec2i(1,0)))+abs(m-mask(p+vec2i(0,1)))+abs(m-mask(p-vec2i(0,1)));
 return vec4f((vec2f(p)+.5)/vec2f(d),select(0.,1.,edge>.5),1.);
}

struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
struct Params { amount:f32, jump:f32, // @default 1 Jump-flood radius in field texels.
};
@fragment fn fs(@location(0) uv:vec2f)->@location(0) vec4f {
 let d=vec2i(textureDimensions(inputTexture));let p=clamp(vec2i(uv*vec2f(d)),vec2i(0),d-1);
 let at=(vec2f(p)+.5)/vec2f(d);let metric=vec2f(f32(d.x)/f32(d.y),1.);
 var best=vec4f(0.);var bestD=1e6;
 for(var y=-1;y<=1;y++){for(var x=-1;x<=1;x++){
 let s=p+vec2i(x,y)*i32(params.jump);if(any(s<vec2i(0))||any(s>=d)){continue;}
 let c=textureLoad(inputTexture,s,0);let delta=(at-c.xy)*metric;let dist=dot(delta,delta);
 if(c.z>.5&&dist<bestD){best=c;bestD=dist;}
 }}return best;
}

