struct Params {
 speed:f32, // @default 0.38 Feed velocity at the uneven lip.
 gravity:f32, // @default 2.2 Downward acceleration for ballistic drops.
 drag:f32, // @default 0.5 Air resistance, scaled by droplet size.
 splash:f32, // @default 1.2 Fraction of incoming momentum redistributed into spray.
 swirl:f32, // @default 1.2 Shared air turbulence; sampled from the middle atlas panel.
 brightness:f32, // @default 0.85 Optical energy in the water.
 velocityShade:f32, // @default 0.6 Speed-dependent highlight contrast.
 grainSize:f32, // @default 1.1 Drop size multiplier.
 aspect:f32, // @default 1.7777778 Width over height in world units.
 motionRate:f32, // @default 0.45 Simulation time scale.
 folds:f32, // @default 0.9 Growth of breakup with falling distance.
 strandLength:f32, // @default 0.038 Exposure of a coarse drop, in simulation seconds.
